import org.springframework.data.mongodb.repository.MongoRepository;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

public interface ProductRepository extends MongoRepository<Product, String> {

    // Simple equality filter
    List<Product> findByCategoryAndStatus(String category, String status);

    // Range filter
    List<Product> findByPriceBetween(double min, double max);

    // Existence check
    boolean existsBySkuCode(String skuCode);

    // With sorting and pagination
    List<Product> findByCategory(
        String category,
        org.springframework.data.domain.Pageable pageable
    );

    // Projection — return only name and price
    List<ProductSummary> findByStatus(String status); // ProductSummary is a projection interface
}

import org.springframework.data.mongodb.repository.Query;
import java.util.List;

public interface OrderRepository extends MongoRepository<Order, String> {

    // ?0 is the first method parameter (zero-indexed)
    @Query("{ 'customerId': ?0, 'status': { $in: ?1 } }")
    List<Order> findByCustomerAndStatuses(String customerId, List<String> statuses);

    // Regex search on name field
    @Query("{ 'items.productName': { $regex: ?0, $options: 'i' } }")
    List<Order> searchByProductName(String namePattern);

    // Fields projection — return only id, status, totalAmount
    @Query(value = "{ 'customerId': ?0 }", fields = "{ 'status': 1, 'totalAmount': 1 }")
    List<Order> findOrderSummariesByCustomer(String customerId);
}

import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
public class ProductSearchService {

    private final MongoTemplate mongoTemplate;

    public ProductSearchService(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    public List<Product> search(String category, Double minPrice, Double maxPrice, String status) {
        Criteria criteria = new Criteria();

        if (category != null) {
            criteria = criteria.and("category").is(category);
        }
        if (minPrice != null && maxPrice != null) {
            criteria = criteria.and("price").gte(minPrice).lte(maxPrice);
        }
        if (status != null) {
            criteria = criteria.and("status").is(status);
        }

        Query query = new Query(criteria)
            .limit(50)
            .with(org.springframework.data.domain.Sort.by("price").ascending());

        return mongoTemplate.find(query, Product.class);
    }
}

