import org.springframework.data.mongodb.core.messaging.ChangeStreamRequest;
import org.springframework.data.mongodb.repository.event.AbstractMongoEventListener;
import com.mongodb.client.model.changestream.ChangeStreamDocument;
import org.bson.Document;

// Spring Data MongoDB 3.x declarative approach
import org.springframework.data.mongodb.core.messaging.Message;
import org.springframework.stereotype.Component;

// NOTE: As of Spring Data MongoDB 3.0+, use MessageListener and MessageListenerContainer
import org.springframework.context.annotation.Bean;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.messaging.*;

@Component
public class OrderChangeListener implements MessageListener<ChangeStreamDocument<Document>, Order> {

    @Override
    public void onMessage(Message<ChangeStreamDocument<Document>, Order> message) {
        Order order = message.getBody(); // mapped to Order POJO
        ChangeStreamDocument<Document> raw = message.getRaw();
        System.out.printf("Change detected — operation: %s, orderId: %s%n",
            raw.getOperationType(), order != null ? order.getId() : "N/A");
    }
}

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.messaging.*;
import org.springframework.data.mongodb.core.query.Criteria;

@Configuration
public class ChangeStreamConfig {

    @Bean
    MessageListenerContainer messageListenerContainer(
            MongoTemplate mongoTemplate,
            OrderChangeListener listener) {

        MessageListenerContainer container =
            new DefaultMessageListenerContainer(mongoTemplate);

        // Subscribe to all inserts and updates on the 'orders' collection
        ChangeStreamRequest<Order> request = ChangeStreamRequest
            .builder(listener)
            .collection("orders")
            .filter(MessageListenerContainerSupport
                .buildFilter(Criteria.where("operationType").in("insert", "update")))
            .publishTo(Order.class)
            .build();

        container.register(request, Order.class);
        container.start();
        return container;
    }
}

import org.springframework.data.mongodb.core.ReactiveMongoTemplate;
import org.springframework.data.mongodb.core.aggregation.Aggregation;
import org.springframework.data.mongodb.core.messaging.ChangeStreamOptions;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Flux;

@Service
public class ReactiveOrderChangeService {

    private final ReactiveMongoTemplate reactiveMongoTemplate;

    public ReactiveOrderChangeService(ReactiveMongoTemplate reactiveMongoTemplate) {
        this.reactiveMongoTemplate = reactiveMongoTemplate;
    }

    public Flux<org.springframework.data.mongodb.core.ChangeStreamEvent<Order>> watchOrders() {
        return reactiveMongoTemplate.changeStream(
            "orders",
            ChangeStreamOptions.builder()
                .filter(Aggregation.newAggregation(
                    Aggregation.match(
                        org.springframework.data.mongodb.core.query.Criteria
                            .where("operationType").is("insert")
                    )
                ))
                .build(),
            Order.class
        );
    }
}

import org.bson.BsonDocument;
import org.springframework.data.mongodb.core.ChangeStreamEvent;
import org.springframework.data.mongodb.core.messaging.ChangeStreamOptions;
import reactor.core.publisher.Flux;

// resumeToken should be persisted in Redis, a DB, or another durable store
public Flux<ChangeStreamEvent<Order>> watchOrdersFromToken(BsonDocument resumeToken) {
    ChangeStreamOptions options = resumeToken != null
        ? ChangeStreamOptions.builder().resumeAt(resumeToken).build()
        : ChangeStreamOptions.empty();

    return reactiveMongoTemplate.changeStream("orders", options, Order.class)
        .doOnNext(event -> {
            // persist the resume token after each successful processing
            BsonDocument token = event.getRaw() != null
                ? event.getRaw().getResumeToken()
                : null;
            if (token != null) {
                persistToken(token); // your implementation
            }
        });
}

private void persistToken(BsonDocument token) {
    // e.g., save to Redis: redisTemplate.opsForValue().set("changestream:orders:token", token.toJson());
}
